<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import axios from 'axios'
import {api,errorMessage,idempotencyKey} from '../../api/http'
import {useAuthStore} from '../../stores/auth'
import {states,blankFormula,blankRoute,clone,type Package,type Formula,type RouteDefinition,type Rule} from './model'
import ProcessLookup from './ProcessLookup.vue'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),pkg=ref<Package|null>(null),v=computed(()=>pkg.value?.currentDefinition),create=computed(()=>route.meta.mode==='create'),editing=computed(()=>route.meta.mode==='edit'),editable=computed(()=>editing.value&&pkg.value?.status==='ACTIVE'&&auth.can('process:package:edit')&&!busy.value)
const createForm=reactive({productId:'',packageCode:''}),formula=reactive<Formula>(blankFormula()),definition=reactive<RouteDefinition>(blankRoute()),error=ref(''),busy=ref(false),conflict=ref(false),tab=ref('formula'),lintResult=ref('尚未校验'),ruleTexts=ref<Record<string,string>>({})
const savedLines=ref<number[]>([]),savedOps=ref<string[]>([]),savedParams=ref<Record<string,string[]>>({})
let pendingBody='',pendingKey=idempotencyKey(),baseline=''
const authored=()=>JSON.stringify({formula:{formulaCode:formula.formulaCode,batchBasisQty:formula.batchBasisQty,unitId:formula.unitId,items:formula.items},definition:{routeCode:definition.routeCode,operations:definition.operations},rules:definition.operations.map(o=>[o.operationCode,ruleTexts.value[o.operationCode]?.trim()||''])}),dirty=computed(()=>!!v.value&&authored()!==baseline)
function sync(){Object.assign(formula,clone(v.value?.formula??blankFormula()));Object.assign(definition,clone(v.value?.route??blankRoute()));for(const op of definition.operations)op.ipcDefinitions??=[];savedLines.value=formula.items.map(i=>i.lineNo);savedOps.value=definition.operations.map(o=>o.operationCode);savedParams.value=Object.fromEntries(definition.operations.map(o=>[o.operationCode,o.parameters.map(p=>p.parameterCode)]));ruleTexts.value=Object.fromEntries(definition.operations.map(o=>[o.operationCode,o.completionRule?JSON.stringify(o.completionRule):'']));baseline=authored();lintResult.value=v.value?.status==='EFFECTIVE'?'当前配置已生效':'配置尚未完整'}
function failure(e:unknown){error.value=axios.isAxiosError(e)?errorMessage(e):(e as Error).message;conflict.value=axios.isAxiosError(e)&&e.response?.status===409}
const listQuery=computed(()=>Object.fromEntries(Object.entries(route.query).filter(([key])=>key!=='versionId')))
async function load(){error.value='';conflict.value=false;pkg.value=null;if(create.value){pkg.value=null;return}try{pkg.value=await api<Package>({url:`/process-packages/${route.params.id}`,});sync()}catch(e){failure(e)}}
function headers(body:unknown){const encoded=JSON.stringify(body);if(encoded!==pendingBody){pendingBody=encoded;pendingKey=idempotencyKey()}return {'Idempotency-Key':pendingKey}}
function requiredReason(){return '工艺配置维护（系统记录）'}
async function createPackage(){busy.value=true;error.value='';try{const p=await api<Package>({url:'/process-packages',method:'POST',data:createForm,headers:headers(createForm)});pendingBody='';await router.push({path:`/process/packages/${p.id}/edit`,query:listQuery.value})}catch(e){failure(e)}finally{busy.value=false}}
function addLine(){formula.items.push({lineNo:Math.max(0,...formula.items.map(i=>i.lineNo))+1,materialId:'',requiredQty:'',unitId:'',overagePct:null,critical:false})}
function renameOperation(op:RouteDefinition['operations'][number],event:Event){const next=(event.target as HTMLInputElement).value;const old=op.operationCode;if(old!==next){ruleTexts.value[next]=ruleTexts.value[old]??'';delete ruleTexts.value[old];for(const other of definition.operations)other.predecessorCodes=other.predecessorCodes.map(c=>c===old?next:c);op.operationCode=next}}
function addOperation(){let n=definition.operations.length+1;while(definition.operations.some(o=>o.operationCode===`OP${n}`))n++;definition.operations.push({operationCode:`OP${n}`,operationName:'',sequenceNo:Math.max(0,...definition.operations.map(o=>o.sequenceNo))+1,requiredRole:null,completionRule:null,predecessorCodes:[],requiredEquipmentType:null,clearanceRequired:false,parameters:[],ipcDefinitions:[]})}
function validateRule(rule:unknown,depth=0):asserts rule is Rule{if(!rule||typeof rule!=='object'||Array.isArray(rule)||depth>=8)throw Error('完成规则格式或层级无效');const r=rule as Rule;if(['ALL','ANY'].includes(r.kind)){if(Object.keys(r).some(k=>!['kind','rules'].includes(k))||!Array.isArray(r.rules)||!r.rules.length||r.rules.length>20)throw Error('组合完成规则需要 1–20 个子规则');r.rules.forEach(c=>validateRule(c,depth+1))}else if(!['EBR_COMPLETE','PARAMETERS_WITHIN_LIMITS','REVIEW_COMPLETE'].includes(r.kind)||Object.keys(r).some(k=>k!=='kind'))throw Error('完成规则仅支持已定义的声明式类型')}
function routePayload(){return {routeCode:definition.routeCode,operations:definition.operations.map(o=>{const raw=ruleTexts.value[o.operationCode]?.trim();const rule=raw?JSON.parse(raw):null;if(rule)validateRule(rule);return {...o,completionRule:rule}})}}
async function save(){busy.value=true;error.value='';try{const body={formula:{formulaCode:formula.formulaCode,batchBasisQty:formula.batchBasisQty,unitId:formula.unitId,items:formula.items},route:routePayload()};pkg.value=await api<Package>({url:`/process-packages/${pkg.value!.id}/current-definition`,method:'PUT',data:body,headers:headers(body)});pendingBody='';conflict.value=false;sync();lintResult.value='保存成功，配置已生效';await router.replace({path:`/process/packages/${pkg.value!.id}`,query:listQuery.value})}catch(e){failure(e)}finally{busy.value=false}}
async function disablePackage(){busy.value=true;error.value='';try{const body={reason:requiredReason(),action:'DISABLE'};await api({url:`/process-packages/${pkg.value!.id}`,method:'PUT',data:body,headers:headers(body)});pendingBody='';await load()}catch(e){failure(e)}finally{busy.value=false}}

onBeforeRouteLeave(()=>!dirty.value||window.confirm('离开页面将放弃未保存的修改，是否继续？'))
watch(()=>route.fullPath,load,{immediate:true})
</script>
<template><main :data-ui-template="create||editing?'T2':'T4'" class="admin-page master-page process-page"><header class="admin-page-header"><div><a-button type="link" @click="router.push({path:'/process/packages',query:listQuery})">← 返回生产工艺列表</a-button><h1>{{create?'新增生产工艺':`${pkg?.packageCode??'生产工艺'} · 工艺定义`}}</h1><p v-if="pkg">{{pkg.productName}} · {{states[pkg.status]}}</p></div><a-space><a-button v-if="!editing&&pkg?.status==='ACTIVE'&&auth.can('process:package:edit')" type="primary" @click="router.push({path:`/process/packages/${pkg!.id}/edit`,query:{...listQuery,versionId:v!.id}})">编辑工艺</a-button></a-space></header>
<a-alert v-if="error" type="error" :message="error" show-icon/><a-alert v-if="conflict" type="warning" message="记录已发生变化，输入已保留。重新加载后核对并继续。"><template #action><a-button @click="load">重新加载</a-button></template></a-alert>
<a-card v-if="create" title="基本信息" class="form-section"><form class="master-form" @submit.prevent="createPackage"><label><span class="form-field-label">生产工艺编码</span><input v-model="createForm.packageCode" class="master-native-input" maxlength="64" required/></label><label><span class="form-field-label">产品</span><ProcessLookup v-model="createForm.productId" resource="products" label="产品"/></label><a-button class="form-full-row" type="primary" html-type="submit" :loading="busy" :disabled="!createForm.productId">创建生产工艺</a-button></form></a-card>
<template v-else-if="pkg&&v"><div class="process-workspace"><a-card class="result-card process-editor"><a-tabs v-model:active-key="tab"><a-tab-pane key="formula" tab="处方 / BOM"><div class="master-form"><label><span class="form-field-label">处方编码</span><input v-model="formula.formulaCode" aria-label="处方编码" class="master-native-input" maxlength="64" :disabled="!editable"/></label><label><span class="form-field-label">基准批量</span><input v-model="formula.batchBasisQty" aria-label="基准批量" class="master-native-input" inputmode="decimal" :disabled="!editable"/></label><label><span class="form-field-label">基准单位</span><ProcessLookup v-model="formula.unitId" resource="units" label="基准单位" :disabled="!editable"/></label></div><div class="process-table-scroll"><table class="process-table"><thead><tr><th>行号</th><th>物料</th><th>理论用量</th><th>单位</th><th>超量 %</th><th>关键物料</th><th>操作</th></tr></thead><tbody><tr v-for="(item,i) in formula.items" :key="item.lineNo"><td>{{item.lineNo}}</td><td><ProcessLookup v-model="item.materialId" resource="materials" :label="`物料 ${item.lineNo}`" :disabled="!editable"/></td><td><input v-model="item.requiredQty" :aria-label="`理论用量 ${item.lineNo}`" class="master-native-input" :disabled="!editable"/></td><td><ProcessLookup v-model="item.unitId" resource="units" :label="`物料单位 ${item.lineNo}`" :disabled="!editable"/></td><td><input v-model="item.overagePct" :aria-label="`超量 ${item.lineNo}`" class="master-native-input" :disabled="!editable"/></td><td><input v-model="item.critical" type="checkbox" :aria-label="`关键物料 ${item.lineNo}`" :disabled="!editable"/></td><td><a-button v-if="editable&&!savedLines.includes(item.lineNo)" danger @click="formula.items.splice(i,1)">移除</a-button></td></tr></tbody></table></div><a-empty v-if="!formula.items.length" description="尚未维护处方物料"/><a-space v-if="editable"><a-button @click="addLine">添加物料</a-button></a-space></a-tab-pane>
<a-tab-pane key="route" tab="工艺路线"><label class="form-inline-row"><span class="form-field-label">路线编码</span><input v-model="definition.routeCode" aria-label="路线编码" class="master-native-input" maxlength="64" :disabled="!editable"/></label><a-card v-for="(op,i) in definition.operations" :key="i" :title="`${op.sequenceNo}. ${op.operationName||'新工序'}`" class="process-operation"><div class="master-form"><label><span class="form-field-label">工序编码</span><input :value="op.operationCode" @input="renameOperation(op,$event)" :aria-label="`工序编码 ${i+1}`" class="master-native-input" maxlength="64" :disabled="!editable||savedOps.includes(op.operationCode)"/></label><label><span class="form-field-label">工序名称</span><input v-model="op.operationName" :aria-label="`工序名称 ${i+1}`" class="master-native-input" maxlength="200" :disabled="!editable"/></label><label><span class="form-field-label">展示顺序</span><input v-model.number="op.sequenceNo" type="number" min="1" class="master-native-input" :disabled="!editable"/></label><label><span class="form-field-label">前置工序</span><a-select show-search option-filter-prop="children" v-model:value="op.predecessorCodes" mode="multiple" :aria-label="`前置工序 ${i+1}`" :disabled="!editable"><a-select-option v-for="prev in definition.operations.filter(p=>p!==op)" :key="prev.operationCode" :value="prev.operationCode">{{prev.operationName||prev.operationCode}}</a-select-option></a-select></label><label><span class="form-field-label">所需角色</span><input v-model="op.requiredRole" class="master-native-input" maxlength="64" :disabled="!editable"/></label><label><span class="form-field-label">设备类型</span><input v-model="op.requiredEquipmentType" class="master-native-input" maxlength="64" :disabled="!editable"/></label><label><span class="form-field-label">需要清场</span><input v-model="op.clearanceRequired" type="checkbox" :disabled="!editable"/></label><label class="form-full-row"><span class="form-field-label">完成规则</span><textarea v-model="ruleTexts[op.operationCode]" :aria-label="`完成规则 ${i+1}`" class="master-native-input" :disabled="!editable" placeholder='{"kind":"PARAMETERS_WITHIN_LIMITS"}'/></label><small class="form-full-row muted">支持 EBR_COMPLETE、PARAMETERS_WITHIN_LIMITS、REVIEW_COMPLETE；可使用 ALL / ANY 组合，留空表示未配置。</small></div><a-button v-if="editable&&!savedOps.includes(op.operationCode)" danger @click="definition.operations.splice(i,1)">移除未保存工序</a-button></a-card><a-empty v-if="!definition.operations.length" description="尚未维护工艺路线"/><a-space v-if="editable"><a-button @click="addOperation">添加工序</a-button></a-space></a-tab-pane>
<a-tab-pane key="ipc" tab="过程检验 IPC"><a-card v-for="op in definition.operations" :key="op.operationCode" :title="`${op.operationCode} · ${op.operationName}`" class="process-operation"><div v-for="(ipc,i) in op.ipcDefinitions" :key="i" class="master-form"><label><span class="form-field-label">IPC 编码</span><input v-model="ipc.ipcCode" class="master-native-input" aria-label="IPC 编码" maxlength="64" :disabled="!editable"/></label><label><span class="form-field-label">检验名称</span><input v-model="ipc.name" class="master-native-input" aria-label="IPC 检验名称" maxlength="200" :disabled="!editable"/></label><label><span class="form-field-label">必检项目</span><input v-model="ipc.required" type="checkbox" aria-label="IPC 必检项目" :disabled="!editable"/></label><label><span class="form-field-label">结果类型</span><select v-model="ipc.resultType" class="master-native-input" aria-label="IPC 结果类型" :disabled="!editable" @change="ipc.lowerLimit=null;ipc.upperLimit=null;ipc.expectedText=null;ipc.unitId=null"><option value="NUMERIC">数值</option><option value="TEXT">文本</option></select></label><template v-if="ipc.resultType==='NUMERIC'"><label><span class="form-field-label">标准下限</span><input v-model="ipc.lowerLimit" class="master-native-input" aria-label="IPC 标准下限" :disabled="!editable"/></label><label><span class="form-field-label">标准上限</span><input v-model="ipc.upperLimit" class="master-native-input" aria-label="IPC 标准上限" :disabled="!editable"/></label><label><span class="form-field-label">检验单位</span><ProcessLookup v-model="ipc.unitId" resource="units" label="IPC 检验单位" allow-clear :disabled="!editable"/></label></template><label v-else><span class="form-field-label">预期结果</span><input v-model="ipc.expectedText" class="master-native-input" aria-label="IPC 预期结果" maxlength="1000" :disabled="!editable"/></label><label><span class="form-field-label">方法及版本引用</span><input v-model="ipc.methodReference" class="master-native-input" aria-label="IPC 方法及版本引用" maxlength="200" :disabled="!editable"/></label><a-button v-if="editable" danger @click="op.ipcDefinitions?.splice(i,1)">移除草稿 IPC</a-button></div><a-button v-if="editable" @click="(op.ipcDefinitions??=[]).push({ipcCode:'',name:'',required:true,resultType:'NUMERIC',lowerLimit:null,upperLimit:null,expectedText:null,unitId:null,methodReference:''})">添加 IPC</a-button></a-card></a-tab-pane><a-tab-pane key="parameters" tab="参数上下限"><a-empty v-if="!definition.operations.length" description="请先在工艺路线中添加工序"/><a-card v-for="op in definition.operations" :key="op.operationCode" :title="`${op.operationCode} · ${op.operationName}`" class="process-operation"><div class="process-table-scroll"><table class="process-table"><thead><tr><th>参数编码</th><th>参数名称</th><th>采集模式</th><th>单位</th><th>下限</th><th>上限</th><th>操作</th></tr></thead><tbody><tr v-for="(p,i) in op.parameters" :key="i"><td><input v-model="p.parameterCode" :aria-label="`参数编码 ${i+1}`" class="master-native-input" maxlength="64" :disabled="!editable||savedParams[op.operationCode]?.includes(p.parameterCode)"/></td><td><input v-model="p.parameterName" :aria-label="`参数名称 ${i+1}`" class="master-native-input" maxlength="200" :disabled="!editable"/></td><td><select v-model="p.acquisitionMode" :aria-label="`采集模式 ${i+1}`" class="master-native-input" :disabled="!editable"><option value="MANUAL">手工</option><option value="AUTO">自动</option><option value="HYBRID">混合</option></select></td><td><ProcessLookup v-model="p.unitId" resource="units" :label="`参数单位 ${i+1}`" allow-clear :disabled="!editable"/></td><td><input v-model="p.lowerLimit" :aria-label="`下限 ${i+1}`" class="master-native-input" :disabled="!editable"/></td><td><input v-model="p.upperLimit" :aria-label="`上限 ${i+1}`" class="master-native-input" :disabled="!editable"/></td><td><a-button v-if="editable&&!savedParams[op.operationCode]?.includes(p.parameterCode)" danger @click="op.parameters.splice(i,1)">移除</a-button></td></tr></tbody></table></div><a-button v-if="editable" @click="op.parameters.push({parameterCode:'',parameterName:'',acquisitionMode:'MANUAL',unitId:null,lowerLimit:null,upperLimit:null})">添加参数</a-button></a-card></a-tab-pane>
</a-tabs></a-card>
<aside><a-card title="操作" class="form-section"><p v-if="lintResult" role="status">{{lintResult}}</p><a-space direction="vertical" style="width:100%"><a-button v-if="editing&&auth.can('process:package:edit')&&pkg.status==='ACTIVE'" type="primary" block :loading="busy" :disabled="conflict" @click="save">保存并生效</a-button><a-button v-if="editing" block :disabled="busy" @click="router.push({path:`/process/packages/${pkg.id}`,query:listQuery})">取消</a-button></a-space></a-card>
<a-card v-if="pkg.status==='ACTIVE'&&auth.can('process:package:update')" title="生产工艺维护" class="form-section"><a-button danger :disabled="busy||dirty||conflict" @click="disablePackage">停用生产工艺</a-button></a-card></aside></div></template></main></template>
<style scoped>
.process-workspace{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:18px;align-items:start}.process-editor{min-width:0}.process-workspace aside{display:grid;gap:16px}.process-table-scroll{overflow-x:auto;margin:18px 0}.process-table{border-collapse:collapse;width:100%;min-width:880px}.process-table th,.process-table td{padding:10px;border:1px solid #e8edf3;text-align:left}.process-table th{background:#f5f8fc;white-space:nowrap}.process-table td{min-width:100px}.process-table td:has(.process-lookup){min-width:200px}.process-operation{margin:16px 0}.process-reason{display:grid;grid-template-columns:84px minmax(0,1fr);align-items:start;gap:0 10px;margin:14px 0}.process-reason>:not(.form-field-label){min-width:0;width:100%;margin-top:0}.process-actions{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.process-digest{overflow-wrap:anywhere;min-width:0}.process-comparison{display:grid;grid-template-columns:1fr 1fr;gap:16px}.process-comparison section{min-width:0}.process-comparison pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f8fc;padding:14px;max-height:600px;overflow:auto}:deep(.process-lookup){display:block;min-width:0;width:100%}:deep(.process-lookup .ant-select){width:100%}@media(max-width:1100px){.process-workspace{grid-template-columns:1fr}.process-comparison{grid-template-columns:1fr}}
</style>
